const ieltsStages=[
{title:'Read for evidence & paraphrase',skill:'Reading',intro:'Separate an exact contradiction from information the text never gives. Paraphrase changes wording while preserving meaning and limits.',context:'A university library extended its evening opening hours during a six-week pilot. Visits after 8 p.m. increased by 30% compared with the previous six weeks, while daytime visits changed little. A voluntary survey suggested that students who worked during the day particularly valued the extra hours. However, the researchers did not collect examination results or compare participants with a randomly selected control group. The report therefore described improved access, rather than improved academic performance, as the clearest benefit. It recommended a longer trial before permanent staffing changes were made.',questions:[
['TRUE / FALSE / NOT GIVEN: Evening visits increased during the pilot.','TRUE',['TRUE','FALSE','NOT GIVEN'],'The text explicitly reports a 30% increase after 8 p.m.'],
['TRUE / FALSE / NOT GIVEN: The pilot lasted twelve weeks.','FALSE',['TRUE','FALSE','NOT GIVEN'],'The text says six weeks, which contradicts twelve.'],
['TRUE / FALSE / NOT GIVEN: Students earned higher examination marks during the pilot.','NOT GIVEN',['TRUE','FALSE','NOT GIVEN'],'Examination results were not collected. The claim cannot be confirmed or contradicted.'],
['Which paraphrase preserves the conclusion?','The strongest evidence concerned access, not exam performance.',['All students improved academically.','The strongest evidence concerned access, not exam performance.','Longer hours caused every student to visit.'],'Keep the original limitation and avoid replacing association with causation.'],
['Type the missing word: A voluntary survey may introduce selection ___.','bias',null,'People who volunteer may differ from those who do not.'],
['Type the missing word: Before making the change permanent, the report recommended a longer ___.','trial',null,'Use the word supported by the text rather than inventing a recommendation.']],task:'Underline the evidence for each answer. Explain why NOT GIVEN differs from FALSE, then write a two-sentence summary without adding an exam-result claim.'},
{title:'Listen for corrections & constraints',skill:'Listening',intro:'Listen for changes of plan, spelling, quantities and word limits. A familiar word in an option may be a distractor if the speaker corrects it.',context:'Good morning. Here are the details for Friday’s study workshop. We originally planned to meet in Room 16, but that room is being repaired, so please go to Room 18 instead. The session begins at 9:30, not 9:00 as the first email stated. Bring a notebook and a pencil; printed materials will be provided. There is no charge for registered students. If you cannot attend, please tell the office by Thursday afternoon so we can offer your place to someone on the waiting list.',questions:[
['Which room is the final meeting place?','Room 18',['Room 16','Room 18','The library'],'“Instead” signals a correction from 16 to 18.'],
['What is the confirmed start time?','9:30',['9:00','9:30','Thursday afternoon'],'The earlier email is corrected by “not 9:00”.'],
['Who should students contact if they cannot attend?','The office',['The library','The office','The repair team'],'Listen for the action required, not merely a familiar place name.'],
['Why should students give notice?','To release a place to someone waiting',['To pay an extra fee','To release a place to someone waiting','To change the room back'],'The speaker explains the purpose of notifying the office.'],
['Type ONE WORD: Bring a notebook and a ___.','pencil',null,'Observe the one-word answer limit.'],
['Type ONE WORD: The workshop takes place on ___.','Friday',null,'Distinguish the day of the event from the cancellation deadline.']],task:'Listen before revealing the transcript. Note the original information and its correction. This device-generated recording is a practice aid, not authentic IELTS test audio.'},
{title:'Write with precision & support',skill:'Writing',intro:'For a 7.0+ destination, develop a clear position, organise ideas, use vocabulary accurately and control a range of sentence forms. Sophisticated words do not compensate for unclear reasoning.',context:'Practice data for Task 1: the proportion of students cycling to a fictional college was 20% in 2010, 28% in 2015 and 35% in 2020. The share travelling by bus was 50%, 45% and 40%, respectively. These figures are invented for practice. Task 2 prompt: Some people believe public libraries should invest more in digital services than printed books. To what extent do you agree or disagree?',questions:[
['Which Task 1 overview is supported?','Cycling increased while bus travel decreased.',['Both forms of travel increased.','Cycling increased while bus travel decreased.','Bus travel fell to zero.'],'An overview identifies the main patterns accurately.'],
['Cycling rose from 20% to 35%. The change is ___.','15 percentage points',['15 percentage points','15 percent of the original figure','35 percentage points'],'The absolute difference is 15 percentage points; the relative increase would be 75%.'],
['Which claim exceeds the provided data?','Cycling increased because parking fees rose.',['Cycling reached 35% in 2020.','Bus travel declined.','Cycling increased because parking fees rose.'],'The figures show a trend, not its cause.'],
['Which sentence appropriately qualifies a claim?','Digital services may improve access for some users.',['Digital services always solve every access problem.','Digital services may improve access for some users.','No user ever needs a printed book.'],'Qualification makes the scope defensible rather than absolute.'],
['Type the missing word: The policy could put funding at ___.','risk',null,'Use a natural collocation rather than substituting an arbitrary advanced synonym.'],
['Type the missing word: This evidence calls the conclusion into ___.','question',null,'“Call into question” means raise doubts, not automatically prove false.']],task:'Task 1: describe the fictional figures in at least 150 words. Task 2: write at least 250 words answering the library question with a clear position and developed support. Ask your teacher to review task response, organisation, vocabulary and grammar.'},
{title:'Speak with development & flexibility',skill:'Speaking',intro:'Develop a relevant answer with a reason, example and reflection. Natural paraphrasing is more useful than memorising an entire speech. Pronunciation and fluency require listening to actual speech.',context:'Part 1: What do you enjoy learning, and why? Part 2: Describe a skill you learned that was difficult at first. Say what it was, how you learned it, who helped you, and why it mattered. Part 3: How can schools help students remain motivated when progress is slow?',questions:[
['Which answer is best developed?','I enjoy cooking because it lets me create something useful; last week I learned to make soup.',['Cooking.','I enjoy cooking because it lets me create something useful; last week I learned to make soup.','This question is about many things in society.'],'A relevant answer adds a reason and a concrete example.'],
['What should you do if you cannot recall a precise word?','Paraphrase its meaning naturally',['Stop speaking for the rest of the task','Paraphrase its meaning naturally','Use an unrelated memorised word'],'Describe what you mean while keeping the message accurate.'],
['Which statement shows appropriate qualification?','Support can help, although students respond differently.',['Every student learns in exactly the same way.','Support can help, although students respond differently.','Motivation is never affected by teaching.'],'Nuance acknowledges variation without losing the main point.'],
['Which is the best use of preparation notes?','Brief prompts for the key points',['A complete memorised script read word for word','Brief prompts for the key points','Only unrelated advanced vocabulary'],'Use notes to organise ideas and speak naturally.'],
['Type the missing preposition: I have made progress ___ speaking.','in',null,'“Make progress in” is a useful collocation.'],
['Type the missing word: Regular practice can build my ___ in speaking. (信心)','confidence',null,'Choose the noun that fits both the meaning and the sentence role.']],task:'Prepare the Part 2 response for one minute, then speak for up to two minutes. Have your teacher listen for fluency, vocabulary, grammar and pronunciation. This app does not record your voice or award a speaking band.'}
];
let ieltsStep=0,ieltsQ=null,ieltsAnswered=false,ieltsTest=null,ieltsTranscript=false,ieltsTimer=null,ieltsSeconds=0;
function ieltsState(){state.ielts??=ieltsStages.map(()=>({attempts:0,correct:0,passed:false}));return state.ielts}
function ieltsOpen(i){return i===0||ieltsState()[i-1].passed}
function renderIELTS(){let g=ieltsStages[ieltsStep],u=ieltsState()[ieltsStep];$('#main').innerHTML=`<div class="eyebrow">YOUR ADVANCED DESTINATION</div><h1>Academic IELTS · aim for 7.0+</h1><p class="sub">A bridge beyond senior high · 四项能力，逐步提升</p><div class="note">Planning target: 7.0+. IELTS has no universal pass mark; institutions set their own requirements. Practice percentages here are not band-score predictions.</div><div class="worksteps">${ieltsStages.map((s,i)=>`<button data-ieltsstep="${i}" class="${ieltsStep===i?'selected':''}">${i+1}. ${s.skill}${ieltsOpen(i)?'':' · Preview'}</button>`).join('')}</div><section class="panel"><div class="eyebrow">${g.skill.toUpperCase()} · ${ieltsOpen(ieltsStep)?'PRACTICE AVAILABLE':'PREVIEW · MASTER THE PREVIOUS STEP TO PRACTISE'}</div><h2>${g.title}</h2><p>${g.intro}</p>${ieltsStep===1?'<div class="readingtools"><button id="ieltslisten">▷ Listen to practice audio</button><button id="ieltsstop">Stop audio</button><button id="ieltstranscript">Show / hide transcript</button></div>':''}${ieltsStep!==1||ieltsTranscript?`<div class="feedback"><p>${g.context}</p></div>`:''}<div class="feedback"><b>Apply the skill</b><p>${g.task}</p></div><div class="workprogress" style="margin-top:20px"><span>${u.attempts} / ${state.target} repetitions · ${u.correct} correct</span><span>${u.passed?'✓ Mastered':'Separate 8/10 check required'}</span></div><div class="readingtools" style="margin-top:15px"><button id="ieltspractice" ${!ieltsOpen(ieltsStep)?'disabled':''}>Practise this skill →</button><button id="ieltstest" ${!ieltsOpen(ieltsStep)||u.attempts<state.target?'disabled':''}>Mastery check</button></div><div id="ieltsquestion"></div></section>${ieltsStep>=2?`<section class="panel"><h2>${ieltsStep===2?'Writing draft':'Speaking preparation notes'}</h2><textarea id="ieltsdraft" placeholder="Your own ideas…">${escape(state.ieltsDrafts?.[ieltsStep]||'')}</textarea><p class="sub">Saved locally. Free writing and speaking require teacher assessment.</p>${ieltsStep===3?'<div class="readingtools"><button id="ieltsprepare">Start 1-minute preparation</button><button id="ieltstalk">Start 2-minute talk</button><button id="ieltstimerstop">Stop timer</button><output id="ieltstimer" aria-live="polite">Ready</output></div>':''}</section>`:''}<div class="panel"><h2>Practise with official resources too</h2><p>This is an original introductory practice bridge, not a full mock exam, official IELTS product or guarantee of a 7.0 score.</p><a href="https://ielts.org/take-a-test/test-types/ielts-academic-test" target="_blank" rel="noopener">Official IELTS Academic format & sample resources ↗</a><p><a href="https://ielts.org/take-a-test/your-results/ielts-scoring-in-detail" target="_blank" rel="noopener">Official scoring information ↗</a></p></div>`;ieltsTest=null;}
function renderIELTSQ(){const q=ieltsQ;$('#ieltsquestion').innerHTML=`<div class="feedback"><div class="eyebrow">${ieltsTest?`MASTERY CHECK ${ieltsTest.answers.length+1}/10`:'SCORED RETRIEVAL'}</div><h3>${escape(q[0])}</h3>${q[2]?`<div class="options">${shuffle(q[2]).map(a=>`<button class="option" data-ieltsanswer="${escape(a)}">${escape(a)}</button>`).join('')}</div>`:'<form id="ieltsform"><label class="screenreader" for="ieltstyped">Your answer</label><input id="ieltstyped" type="text" autocomplete="off" required placeholder="Type your answer…"><button class="primary">Submit →</button></form>'}<div id="ieltsfeedback" role="status"></div></div>`}
function nextIELTSQ(){let qs=ieltsStages[ieltsStep].questions.filter(q=>q[0]!==ieltsQ?.[0]);ieltsQ=qs[Math.floor(Math.random()*qs.length)];ieltsAnswered=false;renderIELTSQ()}
function answerIELTS(a){if(ieltsAnswered||!a.trim())return;ieltsAnswered=true;const ok=a.trim().toLowerCase()===ieltsQ[1].toLowerCase(),u=ieltsState()[ieltsStep];document.querySelectorAll('[data-ieltsanswer]').forEach(b=>b.disabled=true);if($('#ieltstyped')){$('#ieltstyped').disabled=true;$('#ieltsform button').disabled=true}if(ieltsTest){ieltsTest.answers.push(ok);ieltsTest.responses.push({q:ieltsQ,a});if(ieltsTest.answers.length===10){let n=ieltsTest.answers.filter(Boolean).length;if(n>=8){u.passed=true;save()}$('#ieltsquestion').innerHTML=`<div class="feedback"><h2>${n}/10 · ${n>=8?'Practice checkpoint reached':'Keep practising'}</h2><p>This is not an IELTS band score.</p>${ieltsTest.responses.map((r,i)=>`<details><summary>${ieltsTest.answers[i]?'✓':'↻'} ${escape(r.q[0])}</summary><p>Your answer: ${escape(r.a)}<br>Answer: ${escape(r.q[1])}<br>${escape(r.q[3])}</p></details>`).join('')}<button class="primary" id="ieltsback" style="margin-top:15px">Return to skill path →</button></div>`;ieltsTest=null;return}$('#ieltsfeedback').innerHTML='<button class="primary" id="ieltsnext" style="margin-top:15px">Next →</button>';return}u.attempts++;u.correct+=Number(ok);save();const checkButton=document.querySelector('#ieltstest');if(checkButton)checkButton.disabled=u.attempts<state.target;const progress=document.querySelector('.workprogress');if(progress)progress.innerHTML=`<span>${u.attempts} / ${state.target} repetitions · ${u.correct} correct</span><span>${u.passed?'✓ Mastered':'Separate 8/10 check required'}</span>`;$('#ieltsfeedback').innerHTML=`<p>${ok?'✓ Correct.':'Review the distinction.'} ${escape(ieltsQ[3])}<br>Answer: ${escape(ieltsQ[1])}</p><p>${u.attempts}/${state.target} attempts</p><button class="primary" id="ieltsnext">Next question →</button>`}
function startIELTSTimer(n){clearInterval(ieltsTimer);ieltsSeconds=n;const tick=()=>{const o=document.querySelector('#ieltstimer');if(!o){clearInterval(ieltsTimer);return}o.textContent=ieltsSeconds>0?`${Math.floor(ieltsSeconds/60)}:${String(ieltsSeconds%60).padStart(2,'0')}`:'Time complete';if(ieltsSeconds<=0)clearInterval(ieltsTimer);ieltsSeconds--};tick();ieltsTimer=setInterval(tick,1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.ieltsstep!==undefined){ieltsStep=Number(b.dataset.ieltsstep);renderIELTS()}if(b.id==='ieltspractice'&&ieltsOpen(ieltsStep)){ieltsTest=null;nextIELTSQ()}if(b.id==='ieltstest'&&ieltsOpen(ieltsStep)&&ieltsState()[ieltsStep].attempts>=state.target){const qs=ieltsStages[ieltsStep].questions;ieltsTest={answers:[],responses:[],questions:shuffle([...qs,...qs]).slice(0,10)};ieltsQ=ieltsTest.questions[0];ieltsAnswered=false;renderIELTSQ()}if(b.dataset.ieltsanswer!==undefined)answerIELTS(b.dataset.ieltsanswer);if(b.id==='ieltsnext'){if(ieltsTest){ieltsQ=ieltsTest.questions[ieltsTest.answers.length];ieltsAnswered=false;renderIELTSQ()}else nextIELTSQ()}if(b.id==='ieltsback')renderIELTS();if(b.id==='ieltstranscript'){ieltsTranscript=!ieltsTranscript;renderIELTS()}if(b.id==='ieltslisten'){if(!('speechSynthesis'in window))return toast('Audio is unavailable in this browser.');speechSynthesis.cancel();const s=new SpeechSynthesisUtterance(ieltsStages[1].context);s.lang='en-GB';s.rate=.9;speechSynthesis.speak(s)}if(b.id==='ieltsstop'&&'speechSynthesis'in window)speechSynthesis.cancel();if(b.id==='ieltsprepare')startIELTSTimer(60);if(b.id==='ieltstalk')startIELTSTimer(120);if(b.id==='ieltstimerstop'){clearInterval(ieltsTimer);$('#ieltstimer').textContent='Stopped'}});document.addEventListener('submit',e=>{if(e.target.id==='ieltsform'){e.preventDefault();answerIELTS($('#ieltstyped').value)}});document.addEventListener('input',e=>{if(e.target.id==='ieltsdraft'){state.ieltsDrafts??={};state.ieltsDrafts[ieltsStep]=e.target.value;save()}});
